// Extract the incoming WhatsApp message text + sender number
const body = $json.body;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

if (!message) {
  // This was a status update (delivered/read), not a real message
  return [{ json: { is_message: false, from_number: null, text_body: '', interactive_reply_id: '' } }];
}

const fromNumber = message.from; // sender's WhatsApp number
const messageType = message.type; // 'text', 'interactive', etc.
const textBody = messageType === 'text' ? (message.text?.body || '').trim().toLowerCase() : '';
const interactiveReplyId = messageType === 'interactive' ? (message.interactive?.list_reply?.id || message.interactive?.button_reply?.id || '') : '';

return [{
  json: {
    is_message: true,
    from_number: fromNumber,
    message_type: messageType,
    text_body: textBody,
    interactive_reply_id: interactiveReplyId
  }
}];

