={{ (() => {
  const rows = [];
  for (let i = 0; i < 7; i++) {
    const d = $now.minus({ days: i }).setZone('Asia/Kolkata');
    const label = d.toFormat('dd-MMM');
    const iso = d.toFormat('yyyy-MM-dd');
    rows.push({
      id: 'date_' + iso,
      title: (i === 0 ? 'Today' : i === 1 ? 'Yesterday' : label),
      description: label
    });
  }
  return JSON.stringify({
    messaging_product: 'whatsapp',
    to: $json.from_number,
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: 'Swift Strips Reports' },
      body: { text: 'Pick a date to get that day\'s Consumption + Purchase report:' },
      footer: { text: 'Last 7 days shown' },
      action: {
        button: 'Pick a Date',
        sections: [ { title: 'Select Date', rows } ]
      }
    }
  });
})() }}

