// Parse the selected date out of the list_reply id, e.g. 'date_2026-09-10'
const id = $json.interactive_reply_id;
const isoDate = id.replace('date_', '');
const dt = DateTime.fromISO(isoDate, { zone: 'Asia/Kolkata' });

return [{
  json: {
    from_number: $json.from_number,
    selected_iso_date: isoDate,
    selected_year: dt.year,
    selected_month: dt.month,
    selected_day: dt.day,
    selected_month_name: dt.toFormat('MMM_yyyy'),
    selected_label: dt.toFormat('dd-MMM-yyyy')
  }
}];

const ctx = $('Parse Gemini Output1').first().json;
const target = (ctx.contact_name || '').toString().trim().toLowerCase();
const rows = $input.all().map(i => i.json);

const exact = rows.find(r => (r['Name'] || '').toString().trim().toLowerCase() === target);
const partial = !exact && rows.find(r => target && (r['Name'] || '').toString().trim().toLowerCase().includes(target));
const reverse = !exact && !partial && rows.find(r => {
  const n = (r['Name'] || '').toString().trim().toLowerCase();
  return n && target.includes(n);
});
const match = exact || partial || reverse;

return [{
  json: {
    match_found: !!match,
    contact_name: match ? match['Name'] : ctx.contact_name,
    task: ctx.task,
    due_date: ctx.due_date,
    frequency: ctx.frequency,
    from_number: ctx.from_number
  }
}];

