const body = $json.body || $json;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

// EDIT THIS LIST — currently set to YOUR number only, for testing
const BOSS_NUMBERS = [String($vars.SENIOR_PHONE ?? '')];

if (!message || message.type !== 'audio') {
  return [{ json: { is_boss_voice: false } }];
}

const fromNumber = (message.from || '').toString().trim();
const isBoss = BOSS_NUMBERS.includes(fromNumber);

return [{
  json: {
    is_boss_voice: isBoss,
    from_number: fromNumber,
    audio_id: message.audio?.id || '',
    mime_type: message.audio?.mime_type || 'audio/ogg'
  }
}];

