const resp = $json;
let text = '';
try {
  text = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch (e) {}

let parsed;
try {
  parsed = JSON.parse(String(text).replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { parse_ok: false, raw: text, from_number: $('Extract Voice Task1').first().json.from_number } }];
}

if (!parsed || !parsed.contact_name || !parsed.task || !parsed.due_date) {
  return [{ json: { parse_ok: false, raw: text, parsed, from_number: $('Extract Voice Task1').first().json.from_number } }];
}

return [{
  json: {
    parse_ok: true,
    contact_name: String(parsed.contact_name).trim(),
    task: String(parsed.task).trim(),
    due_date: String(parsed.due_date).trim(),
    frequency: parsed.frequency || 'one-time',
    from_number: $('Extract Voice Task1').first().json.from_number
  }
}];

const rows = $input.all().map(i => i.json);
const headerRow = 3;

const dataRows = rows.filter(r => {
  const contact = (r['Contact Name'] || '').toString().trim();
  const task = (r['Task'] || '').toString().trim();
  const taskId = (r['Task ID'] || '').toString().trim();
  return contact !== '' || task !== '' || taskId !== '';
});

const maxRow = dataRows.reduce((m, r) => Math.max(m, Number(r.row_number) || 0), headerRow);
const nextRow = maxRow + 1;
const ctx = $('Match Contact').first().json;

return [{
  json: {
    row_number: nextRow,
    'Contact Name': ctx.contact_name,
    'Task': ctx.task,
    'Due Date': ctx.due_date,
    'Frequency': ctx.frequency,
    from_number: ctx.from_number
  }
}];

const target = Number($('Find Next Blank Row1').first().json.row_number);
const rows = $input.all().map(i => i.json);
const row = rows.find(r => Number(r.row_number) === target);
const from_number = $('Find Next Blank Row1').first().json.from_number;

if (!row) {
  return [{ json: { write_confirmed: false, from_number, 'Contact Name': $('Find Next Blank Row1').first().json['Contact Name'], 'Task': $('Find Next Blank Row1').first().json['Task'] } }];
}

return [{
  json: {
    write_confirmed: true,
    'Task ID': (row['Task ID'] || '').toString().trim(),
    'Contact Name': (row['Contact Name'] || '').toString().trim(),
    'Phone Number': (row['Phone Number'] || '').toString().trim(),
    'Task': (row['Task'] || '').toString().trim(),
    'Due Date': (row['Due Date'] || '').toString().trim(),
    from_number
  }
}];

